ST.xhtml:
// =============================================================================
// 场景：多通道温度日志需要等宽对齐显示（操作员眼睛对齐查异常），每条
//       温度字段固定宽度 8 字符 + 2 位小数。手写 LREAL_TO_FMTSTR 只能控
//       精度不能控宽度，得手动补空格——本函数一步完成。
// 价值：相比 LREAL_TO_FMTSTR + CONCAT 空格补齐两步，本函数单调用搞定
//       宽度 + 精度 + 对齐三件事；FB_FormatString 更适合多字段模板，
//       本函数适合精细控制单字段。
// 验证步骤：
//   1. 登录后 sFormattedLog = ''，nFormatErrorCode = 0。
//   2. 在线写 bFormatRequest := TRUE。
//   3. 观察 sFormattedLog 类似 '   25.38'（右对齐、空格补齐到宽 8、2 位小数四舍五入）。
//      nFormatErrorCode 应为 0（成功）。
//   4. 把 rChannelTemperature 改成 -3.5 再触发：观察输出会含负号且仍宽 8。
//   5. 把 bLAlign 在 F_FormatArgToStr 调用中改为 TRUE 验证左对齐——这是本
//      函数相对 LREAL_TO_FMTSTR 的核心增量价值。
// =============================================================================

// 单次格式化：固定宽度 8，2 位小数，右对齐，浮点 'f' 格式
IF bFormatRequest THEN
    nFormatErrorCode := F_FormatArgToStr(
        bSign      := FALSE,
        bBlank     := FALSE,
        bNull      := FALSE,
        bHash      := FALSE,
        bLAlign    := FALSE,
        bWidth     := TRUE,
        iWidth     := 8,
        iPrecision := 2,
        eFmtType   := E_TypeFieldParam.fix_e,
        arg        := F_LREAL(rChannelTemperature),
        sOut       := sFormattedLog);
    bFormatRequest := FALSE;
END_IF;
